#!/usr/bin/env bash
set -euo pipefail

root=/opt/alps/apertus2-rocm
# shellcheck source=Alps-Images/common/package-helpers.sh
source /opt/alps/package-helpers.sh
# shellcheck source=Alps-Images/apps/apertus-2/sources/rocm/versions.env
source "${root}/versions.env"
# Generated by the canonical base-image installer.
# shellcheck source=/dev/null
source /opt/alps/env/alps-rocm-build.env

export ROCM_HOME="${ROCM_BUILD_PREFIX:?missing Alps ROCm SDK prefix}"
export PATH="${ROCM_HOME}/bin:${ROCM_HOME}/llvm/bin:${PATH}"
export PYTORCH_ROCM_ARCH=gfx942 HIP_ARCHITECTURES=gfx942
export MAX_JOBS="${APERTUS_BUILD_JOBS:-8}" CMAKE_BUILD_PARALLEL_LEVEL="${APERTUS_BUILD_JOBS:-8}"
export PIP_CONSTRAINT="${root}/base-pins.txt"
# clang 23 must discover the SDK itself; ROCM_PATH/HIP_PATH force a broken HIP
# language probe in the wheel-only layout. ROCM_HOME still guides torch builds.
unset ROCM_PATH HIP_PATH

checkout_source() {
    local name=$1 repo=$2 ref=$3 dest=$4
    git init -q "$dest"
    git -C "$dest" remote add origin "$repo"
    git -C "$dest" fetch --depth 1 origin "$ref"
    git -C "$dest" checkout -q --detach FETCH_HEAD
    test "$(git -C "$dest" rev-parse HEAD)" = "$ref"
    printf '%s %s %s\n' "$name" "$repo" "$ref" >> "${root}/source-pins.txt"
}

case "${1:?installation group required}" in
    system)
        test "$(uname -m)" = x86_64
        python3 - <<'PY'
import sys
from importlib import metadata
from pathlib import Path
import torch

assert sys.version_info[:2] == (3, 12), sys.version
assert torch.version.hip is not None and torch.version.cuda is None, torch.__version__
pins = []
for name in ('torch', 'torchvision', 'torchaudio', 'triton', 'pytorch-triton',
             'pytorch-triton-rocm', 'triton-rocm', 'numpy'):
    try:
        pins.append(f'{name}=={metadata.version(name)}')
    except metadata.PackageNotFoundError:
        if name in ('torch', 'numpy'):
            raise
Path('/opt/alps/apertus2-rocm/base-pins.txt').write_text('\n'.join(pins) + '\n')
PY
        apt_get update
        apt_get install -y --no-install-recommends \
            build-essential ca-certificates cmake git libibverbs-dev libnl-3-dev \
            libnl-route-3-dev libnuma-dev ninja-build pkg-config python3-dev
        rm -rf /var/lib/apt/lists/*
        pip_install python3 --no-cache-dir --no-deps -r "${root}/requirements.lock"
        ;;
    uccl)
        bash "${root}/install-uccl.sh"
        ;;
    transformer-engine)
        checkout_source transformer-engine "$TE_REPO" "$TE_REF" /tmp/apertus2-te
        git -C /tmp/apertus2-te submodule update --init --recursive --depth 1
        for patch_file in "${root}"/patches/transformer-engine/*.patch; do
            git -C /tmp/apertus2-te apply --check "$patch_file"
            git -C /tmp/apertus2-te apply "$patch_file"
        done
        for patch_file in "${root}"/patches/ck-jit/*.patch; do
            git -C /tmp/apertus2-te/3rdparty/ck_jit apply --check "$patch_file"
            git -C /tmp/apertus2-te/3rdparty/ck_jit apply "$patch_file"
        done
        export NVTE_USE_ROCM=1 NVTE_FRAMEWORK=pytorch NVTE_ROCM_ARCH=gfx942
        export NVTE_CK_JIT=1 NVTE_FUSED_ATTN_CK=1 NVTE_FUSED_ATTN_AOTRITON=0
        export NVTE_BUILD_MAX_JOBS="$MAX_JOBS"
        # HIP-mode sources use the canonical bundled RCCL headers, not just the
        # wheel core's implicit HIP include directory.
        export CPLUS_INCLUDE_PATH="${RCCL_INCLUDE_DIR}${CPLUS_INCLUDE_PATH:+:${CPLUS_INCLUDE_PATH}}"
        pip_install python3 --no-cache-dir --no-build-isolation --no-deps /tmp/apertus2-te
        rm -rf /tmp/apertus2-te
        ;;
    training)
        checkout_source emerging-optimizers "$EMERGING_OPTIMIZERS_REPO" "$EMERGING_OPTIMIZERS_REF" /tmp/apertus2-muon
        pip_install python3 --no-cache-dir --no-build-isolation --no-deps /tmp/apertus2-muon
        checkout_source flash-linear-attention "$FLA_REPO" "$FLA_REF" /tmp/apertus2-fla
        pip_install python3 --no-cache-dir --no-build-isolation --no-deps /tmp/apertus2-fla
        checkout_source causal-conv1d "$CAUSAL_CONV1D_REPO" "$CAUSAL_CONV1D_REF" /tmp/apertus2-conv
        CAUSAL_CONV1D_FORCE_BUILD=TRUE pip_install python3 --no-cache-dir --no-build-isolation --no-deps /tmp/apertus2-conv
        rm -rf /tmp/apertus2-muon /tmp/apertus2-fla /tmp/apertus2-conv
        ;;
    megatron)
        # Ship the tested training checkout, unlike the CUDA images which expect
        # users to mount one. No CUDA-specific extras are requested from its metadata.
        checkout_source megatron "$MEGATRON_REPO" "$MEGATRON_REF" /opt/megatron-lm
        pip_install python3 --no-cache-dir --no-build-isolation --no-deps -e /opt/megatron-lm
        make -C /opt/megatron-lm/megatron/core/datasets -j"$MAX_JOBS"
        python3 -m pip freeze > "${root}/installed-packages.txt"
        ;;
    *)
        printf 'Unknown ROCm installation group: %s\n' "$1" >&2
        exit 2
        ;;
esac
